+      w: 2.65,
+      h: 0.4,
+      fontFace: "Arial",
+      fontSize: 12,
+      color: theme.light,
+      align: "right"
+    });
+  }
+}
+
+function addFooter(slide, index, total, theme) {
+  // Small page badge bottom-right.
+  slide.addShape("roundRect", {
+    x: 12.25,
+    y: 7.07,
+    w: 0.9,
+    h: 0.38,
+    fill: { color: theme.primary },
+    line: { color: theme.primary },
+    radius: 0.12
+  });
+  slide.addText(`${index}/${total}`, {
+    x: 12.25,
+    y: 7.13,
+    w: 0.9,
+    h: 0.28,
+    fontFace: "Arial",
+    fontSize: 12,
+    color: "FFFFFF",
+    align: "center"
+  });
+}
+
+function addKpi(slide, { x, y, w, title, value, note }, theme) {
+  slide.addShape("roundRect", {
+    x,
+    y,
+    w,
+    h: 1.05,
+    fill: { color: "FFFFFF" },
+    line: { color: theme.light, width: 1 },
+    radius: 0.18
+  });
+  slide.addText(title, {
+    x: x + 0.22,
+    y: y + 0.14,
+    w: w - 0.44,
+    h: 0.3,
+    fontFace: "Arial",
+    fontSize: 12,
+    color: theme.secondary
+  });
+  slide.addText(value, {
+    x: x + 0.22,
+    y: y + 0.43,
+    w: w - 0.44,
+    h: 0.36,
+    fontFace: "Arial",
+    fontSize: 24,
+    color: theme.primary,
+    bold: true
+  });
+  if (note) {
+    slide.addText(note, {
+      x: x + 0.22,
+      y: y + 0.78,
+      w: w - 0.44,
+      h: 0.22,
+      fontFace: "Arial",
+      fontSize: 10,
+      color: theme.secondary
+    });
+  }
+}
+
+function addBullets(slide, x, y, w, bullets, theme) {
+  const fontSize = 14;
+  slide.addText(
+    bullets
+      .map((b) => `• ${b}`)
+      .join("\n"),
+    {
+      x,
+      y,
+      w,
+      h: clamp(0.3 * bullets.length + 0.3, 0.8, 3.2),
+      fontFace: "Arial",
+      fontSize,
+      color: theme.primary,
+      valign: "top",
+      lineSpacingMultiple: 1.2
+    }
+  );
+}
+
+module.exports = {
+  THEME,
+  clamp,
+  fmtUSDShort,
+  addHeader,
+  addFooter,
+  addKpi,
+  addBullets
+};
+
*** End Patch
PATCH

