+const path = require("path");
+const pptxgen = require("pptxgenjs");
+
+const { THEME } = require("./theme");
+
+function build() {
+  const pres = new pptxgen();
+  pres.layout = "LAYOUT_16x9";
+
+  // Basic theme fonts
+  pres.author = "pptx-generator";
+  pres.company = "";
+  pres.subject = "Ethereum supply dynamics";
+  pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium";
+
+  const slideFiles = [
+    "slide-01.js",
+    "slide-02.js",
+    "slide-03.js",
+    "slide-04.js",
+    "slide-05.js",
+    "slide-06.js",
+    "slide-07.js",
+    "slide-08.js"
+  ];
+
+  for (const file of slideFiles) {
+    // eslint-disable-next-line global-require, import/no-dynamic-require
+    const mod = require(path.join(__dirname, file));
+    mod.createSlide(pres, THEME);
+  }
+
+  const outPath = path.join(__dirname, "output", "presentation.pptx");
+  return pres.writeFile({ fileName: outPath });
+}
+
+if (require.main === module) {
+  build().catch((err) => {
+    // eslint-disable-next-line no-console
+    console.error(err);
+    process.exit(1);
+  });
+}
+
+module.exports = { build };
+
*** End Patch
PATCH

